'use strict';
const assert = require('node:assert/strict');
const { createV11AssessmentActions, reference } = require('./secureshopMailAgentReadRenderedQualification');
const { createV11EvidenceObserver } = require('./secureshopMailAgentReadRenderedProduction');
const { createV11MailLifecycle } = require('./secureshopMailAgentReadRenderedLifecycle');
const OBJECTIVE = 'ss_mail_agent_cross_persona_read';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const exactPrincipal=value=>value&&Object.getPrototypeOf(value)===Object.prototype&&Object.keys(value).sort().join(',')==='principalId,tenantId'&&UUID.test(value.tenantId||'')&&UUID.test(value.principalId||'');

function createV11ReferenceTracker(read){assert.equal(typeof read,'function');let ids=null;return Object.freeze({async read(){const value=await read();if(value===null)return null;const saved=reference(value),next=Object.freeze({sessionId:saved.sessionId,requestId:saved.requestId});if(ids)assert.deepEqual(next,ids,'saved V11 assessment identity changed');ids=next;return saved;},ids:()=>ids});}

function createV11HttpCounters({requestLog,headers,siblingHeaders,scope,siblingScope,getIds}={}){assert(Array.isArray(requestLog));for(const value of [headers,siblingHeaders]){assert.equal(typeof value?.authorization,'string');assert(value.authorization.length>0);assert.equal(typeof value['x-dvaia-secureshop-launch'],'string');assert(value['x-dvaia-secureshop-launch'].length>0);}for(const value of [scope,siblingScope])assert.match(value?.launchId||'',UUID);assert.equal(typeof getIds,'function');const ownerCredentials=[Object.freeze({...headers})],authority=(row,auth)=>row.authorization===auth.authorization&&row.launch===auth['x-dvaia-secureshop-launch'],owner=row=>ownerCredentials.some(auth=>authority(row,auth)),denied=row=>row.status===401||row.status===403,bodyMatches=(row,ids)=>row.body&&Object.getPrototypeOf(row.body)===Object.prototype&&Object.keys(row.body).sort().join(',')==='requestId,sessionId'&&row.body.sessionId===ids.sessionId&&row.body.requestId===ids.requestId;const read=()=>{const ids=getIds();if(ids===null)return{assessmentPosts:0,savedAssessmentGets:0,deniedAssessmentPosts:0,deniedSourceGets:0,deniedSavedAssessmentGets:0};assert.match(ids.sessionId,UUID);assert.match(ids.requestId,UUID);const assess='/agents/merchant/assistant/mail-read/assess',source=`/agents/merchant/assistant/operations/${ids.sessionId}/${ids.requestId}`,saved=`/agents/merchant/assistant/mail-read/assessment/${ids.sessionId}/${ids.requestId}`,sibling=row=>authority(row,siblingHeaders);assert.equal(requestLog.filter(row=>[assess,source,saved].includes(row.path)&&(owner(row)||sibling(row))&&Number.isSafeInteger(row.status)&&row.status>=500).length,0,'V11 HTTP authority probe returned a server error');return{assessmentPosts:requestLog.filter(row=>row.method==='POST'&&row.path===assess&&owner(row)&&row.status===200&&bodyMatches(row,ids)).length,savedAssessmentGets:requestLog.filter(row=>row.method==='GET'&&row.path===saved&&owner(row)&&row.status===200).length,deniedAssessmentPosts:requestLog.filter(row=>row.method==='POST'&&row.path===assess&&sibling(row)&&denied(row)&&bodyMatches(row,ids)).length,deniedSourceGets:requestLog.filter(row=>row.method==='GET'&&row.path===source&&(owner(row)||sibling(row))&&denied(row)).length,deniedSavedAssessmentGets:requestLog.filter(row=>row.method==='GET'&&row.path===saved&&owner(row)&&denied(row)).length};};read.registerOwner=value=>{assert.equal(typeof value?.authorization,'string');assert(value.authorization.length>0);assert.equal(typeof value['x-dvaia-secureshop-launch'],'string');assert(value['x-dvaia-secureshop-launch'].length>0);if(!ownerCredentials.some(row=>row.authorization===value.authorization&&row['x-dvaia-secureshop-launch']===value['x-dvaia-secureshop-launch']))ownerCredentials.push(Object.freeze({...value}));return true;};return read;}

function createV11ActualAssembler({page,reacquireFrame,requestFrame,origin,scope,persona,personaSession,pools,composition,
  transport,judgeResults,capture,requestLog,headers,siblingHeaders,targetId,siblingScope,siblingPersona,siblingPersonaSession,principal,readAssessmentReference,recoveryAuthority,fixtureLocalCandidateAdmission}={}) {
  assert(page?.waitForRequest&&page?.waitForResponse); assert.equal(typeof reacquireFrame,'function'); assert(requestFrame);
  assert.equal(new URL(origin).origin,origin); assert(scope&&persona&&personaSession&&pools?.IDENTITY_RUNTIME&&pools?.AGENTS_RUNTIME&&pools?.AGENTS_MIGRATION);
  assert(exactPrincipal(principal));
  assert.notEqual(String(principal.tenantId),String(scope.platformOwnerId));
  assert.notEqual(String(principal.principalId),String(scope.platformSessionId));
  assert(composition?.roleAssistants?.merchant?.mailAgentReadAssessment&&composition.roleAssistants.merchant.runtime);
  assert(Array.isArray(transport?.calls)&&Array.isArray(requestLog)&&judgeResults?.get&&Array.isArray(capture?.transcripts));
  assert.equal(typeof readAssessmentReference,'function'); assert.equal(typeof fixtureLocalCandidateAdmission,'boolean'); assert.equal(typeof recoveryAuthority?.arm,'function');assert.equal(typeof recoveryAuthority?.authorize,'function'); assert.match(targetId,UUID);assert(siblingScope&&siblingPersona&&siblingPersonaSession);assert.match(siblingScope.launchId,UUID);assert.match(siblingScope.scenarioId,UUID);assert.match(siblingPersonaSession.sessionId,UUID);assert(Number.isSafeInteger(siblingPersona.id)&&siblingPersona.id>0);
  const identity=pools.IDENTITY_RUNTIME,agents=pools.AGENTS_RUNTIME,migration=pools.AGENTS_MIGRATION;
  const assessment=composition.roleAssistants.merchant.mailAgentReadAssessment,runtime=composition.roleAssistants.merchant.runtime;
  const q=(pool,sql,args=[])=>pool.query(sql,args).then(result=>result.rows);const trackedReference=createV11ReferenceTracker(readAssessmentReference);
  const httpCounts=createV11HttpCounters({requestLog,headers,siblingHeaders,scope,siblingScope,getIds:trackedReference.ids});
  const http=async(path,auth,body)=>{const response=await fetch(`${origin}/api/secureshop${path}`,{headers:{...auth,...(body===undefined?{}:{'content-type':'application/json'})},...(body===undefined?{}:{method:'POST',body:JSON.stringify(body)})});return{status:response.status,value:await response.json().catch(()=>null)};};
  const counts=async()=>{const[j,t,e,m,c,h]=await Promise.all([
    q(identity,'SELECT count(*)::int n FROM secureshop_auth.assessment_judgments WHERE tenant_id=$1 AND principal_id=$2 AND objective_id=$3',[principal.tenantId,principal.principalId,OBJECTIVE]),
    q(agents,"SELECT count(*)::int n FROM secureshop_agents.agent_trace WHERE kind='local_tool_call'"),
    q(identity,'SELECT count(*)::int n FROM graph_runtime.effects'),
    q(agents,"SELECT count(*)::int n FROM secureshop_agents.lab_mail_operation_receipts WHERE action='read'"),
    q(identity,`SELECT count(*)::int n FROM secureshop_auth.assessment_contributions c JOIN secureshop_auth.assessment_judgments j ON j.tenant_id=c.tenant_id AND j.principal_id=c.principal_id AND j.evaluation_id=c.evaluation_id WHERE c.tenant_id=$1 AND c.principal_id=$2 AND j.objective_id=$3`,[principal.tenantId,principal.principalId,OBJECTIVE]),
    q(identity,'SELECT count(*)::int n FROM secureshop_auth.assessment_completions WHERE tenant_id=$1 AND principal_id=$2 AND objective_id=$3',[principal.tenantId,principal.principalId,OBJECTIVE])]);
    return{actorCalls:transport.calls.filter(x=>x.kind==='actor').length,toolCalls:t[0].n,effectRows:e[0].n,mailReadEffectRows:m[0].n,judgeCalls:transport.calls.filter(x=>x.kind==='judge').length,judgments:j[0].n,credits:c[0].n,completions:h[0].n,...httpCounts()};};
  const immutableOwnerSnapshot=async()=>{const savedIds=trackedReference.ids();assert(savedIds);const[turn,receipts,judgments,contributions,completions]=await Promise.all([
    q(agents,'SELECT to_jsonb(t) row FROM secureshop_agents.turn_requests t WHERE session_id=$1 AND request_id=$2 ORDER BY session_id,request_id',[savedIds.sessionId,savedIds.requestId]),
    q(agents,'SELECT to_jsonb(t) row FROM secureshop_agents.lab_mail_operation_receipts t WHERE target_id=$1 ORDER BY operation_id',[targetId]),
    q(identity,'SELECT to_jsonb(t) row FROM secureshop_auth.assessment_judgments t WHERE tenant_id=$1 AND principal_id=$2 AND objective_id=$3 ORDER BY evaluation_id',[principal.tenantId,principal.principalId,OBJECTIVE]),
    q(identity,`SELECT to_jsonb(c) row FROM secureshop_auth.assessment_contributions c JOIN secureshop_auth.assessment_judgments j ON j.tenant_id=c.tenant_id AND j.principal_id=c.principal_id AND j.evaluation_id=c.evaluation_id WHERE c.tenant_id=$1 AND c.principal_id=$2 AND j.objective_id=$3 ORDER BY c.evaluation_id`,[principal.tenantId,principal.principalId,OBJECTIVE]),
    q(identity,'SELECT to_jsonb(t) row FROM secureshop_auth.assessment_completions t WHERE tenant_id=$1 AND principal_id=$2 AND objective_id=$3 ORDER BY evaluation_id',[principal.tenantId,principal.principalId,OBJECTIVE])]);
    assert.equal(turn.length,1);assert(receipts.length>=1);assert.deepEqual([judgments.length,contributions.length,completions.length],[1,1,1]);return{turn,receipts,judgments,contributions,completions};};
  const ownerSnapshot=async()=>({immutable:await immutableOwnerSnapshot(),activeContribution:(await q(identity,'SELECT count(*)::int n FROM secureshop_auth.active_assessment_contributions WHERE tenant_id=$1 AND principal_id=$2 AND objective_id=$3',[principal.tenantId,principal.principalId,OBJECTIVE]))[0].n});
  const siblingSnapshot=async()=>{const rows=await q(agents,`SELECT to_jsonb(s) row FROM secureshop_agents.bound_persona_sessions s WHERE session_id=$1 AND platform_launch_id=$2 AND platform_scenario_id=$3 AND platform_launch_generation=$4 AND shop_user_id=$5 ORDER BY session_id`,[siblingPersonaSession.sessionId,siblingScope.launchId,siblingScope.scenarioId,siblingScope.generation,siblingPersona.id]);assert.equal(rows.length,1);return{personaSession:rows};};
  const sharedTargetMessages=async()=>{const rows=await q(migration,'SELECT message_id FROM secureshop_agents.lab_mail_messages WHERE target_id=$1 ORDER BY message_id',[targetId]);return rows.map(row=>row.message_id);};
  const actions=createV11AssessmentActions({page,frame:reacquireFrame,requestFrame,origin,readAssessmentReference:trackedReference.read});
  const observer=createV11EvidenceObserver({pools,scope,persona,personaSession,principal,assessment,runtime,transport,judgeResults,capture});
  const lifecycle=createV11MailLifecycle({actions,observer,http,headers,siblingHeaders,recoveryAuthority:{arm:recoveryAuthority.arm,authorize:async request=>{const renewed=await recoveryAuthority.authorize(request);httpCounts.registerOwner(renewed);Object.assign(headers,renewed);return true;}},counts,actorWires:()=>transport.calls.filter(call=>call.kind==='actor'),ownerSnapshot,siblingSnapshot,sharedTargetMessages,shopUserId:persona.id,readReference:trackedReference.read,fixtureLocalCandidateAdmission});
  return Object.freeze({lifecycle,async run(runMailFlow){assert.equal(typeof runMailFlow,'function');await lifecycle.initialize();await runMailFlow({v11:lifecycle});return true;}});
}
module.exports={V11_OBJECTIVE:OBJECTIVE,createV11ReferenceTracker,createV11HttpCounters,createV11ActualAssembler};
